    "bk-lat": ["Grands dorsaux", "Largeur. Tirages, tractions et pull-over."], "bk-mid": ["Milieu du dos", "Rhomboïdes et trapèze moyen. Rowings coudes ouverts."], "bk-low": ["Bas du dos", "Érecteurs du rachis. Soulevés de terre et charnières."],
